def flood_fill(grid, sr, sc, new_value):
    if sr < 0 or sr >= len(grid) or sc < 0 or sc >= len(grid[0]):
        return [row[:] for row in grid]
    original_value = grid[sr][sc]
    if original_value == new_value:
        return [row[:] for row in grid]
    visited = set()
    queue = deque([(sr, sc)])
    visited.add((sr, sc))
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and (nr, nc) not in visited:
                if grid[nr][nc] == original_value:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    result = [row[:] for row in grid]
    for r, c in visited:
        result[r][c] = new_value
    return result
```

