def intersection_car_pass_count(events, green_duration):
    # The light for N/S is green at ticks [0, green_duration)
    # Then E/W is green at ticks [green_duration, 2 * green_duration)
    # Then N/S again at [2 * green_duration, 3 * green_duration), etc.
    table = [[], [], [], []]
    for t, d in events:
        table['NSWE'.index(d)].append(t)
    pass_count = 0
    start = 0
    while start < t:
        end = start + green_duration
        # N/S, S/N, E/W and W/E share a phase, each lasting `green_duration` ticks
        for i in range(2):
            for t in table[i]:
                if start <= t < end:
                    pass_count += 1
            for t in table[i + 2]:
                if start <= t < end:
                    pass_count += 1
        start = end
    return pass_count
```

