def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    red_a, green_a, yellow_a = durations_a
    red_b, green_b, yellow_b = durations_b
    period_a = red_a + green_a + yellow_a
    period_b = red_b + green_b + yellow_b

    green_interval_a = (red_a, red_a + green_a)
    green_interval_b = (red_b, red_b + green_b)
    overlap_start = max(green_interval_a[0], green_interval_b[0])
    overlap_end = min(green_interval_a[1], green_interval_b[1])
    if overlap_start >= overlap_end:
        return 0

    # Number of full period pairs and remainder ticks
    full_pairs = n_ticks // (period_a * period_b)
    remainder_ticks = n_ticks % (period_a * period_b)
    overlaps_per_pair = max(overlap_end - overlap_start, 0)
    total_overlaps = full_pairs * overlaps_per_pair

    # Count overlaps in the remaining ticks
    for t in range(remainder_ticks):
        t_mod_a = t % period_a
        t_mod_b = t % period_b
        if green_interval_a[0] <= t_mod_a < green_interval_a[1] and green_interval_b[0] <= t_mod_b < green_interval_b[1]:
