def is_convex_polygon(points):
    from functools import reduce

    n = len(points)
    if n < 3:
        return False
    if any(points[i] == points[i + 1] for i in range(n - 1)):
        return False
    if any(points[-1] == points[0]):
        return False
    if n == 3:
        return True
    pairs = [(points[i], points[(i + 1) % n], points[(i + 2) % n])
             for i in range(n)]
    return reduce(set.__and__,
                  (side_sign(p, q, r) for p, q, r in pairs),
                  {1, -1}) == {1, -1}

def side_sign(p, q, r):
    # sign of (q - p) cross (r - p)
