@lru_cache
def _count(pos, end_row, end_col, grid):
    r, c = pos
    if r > end_row or c > end_col or grid[r][c]:
        return 0
    if r == end_row and c == end_col:
        return 1
    return _count(r, c + 1, end_row, end_col, grid) + _count(r + 1, c, end_row, end_col, grid)
