    scheme = url[:dot]
    remainder = url[dot + 3:]
    question = remainder.find('?')
    slash = remainder.find('/')
    take = min(slash, question) if slash != -1 and question != -1 else (slash if slash != -1 else question)
    host = remainder[:take] if take != -1 else remainder
    if take != -1 and remainder[take] == '/':
