def rate_limiter_allowed(timestamps, limit, window):
    result = []
    for t in timestamps:
        count = 0
        for prev in timestamps:
            if prev > t - window:
                count += 1
                if count > limit:
                    result.append(False)
                    break
        else:
            result.append(True)
    return result
```

