from collections import defaultdict

def multi_account_balances(events):
    accounts = defaultdict(int)
    for msg in events:
        if msg[0] == 'deposit':
            _, name, amount = msg
            if amount < 0:
                raise ValueError
            accounts[name] += amount
        elif msg[0] == 'withdraw':
            _, name, amount = msg
            if amount < 0:
                raise ValueError
            if name in accounts and accounts[name] >= amount:
                accounts[name] -= amount
        elif msg[0] == 'transfer':
            _, from_name, to_name, amount = msg
            if amount < 0 or from_name == to_name:
                raise ValueError
            if from_name in accounts and accounts[from_name] >= amount:
                accounts[to_name] += amount
                accounts[from_name] -= amount
        else:
            raise ValueError
    return dict(accounts)
```

