def intersection_car_pass_count(events, green_duration):
    n_green_ticks = (green_duration + 1) // 2
    s_green_ticks = green_duration // 2
    e_green_ticks = n_green_ticks
    w_green_ticks = s_green_ticks
    total = 0
    for tick, direction in events:
        if direction in ('N', 'S'):
            if tick < n_green_ticks and direction == 'N':
                total += 1
            elif tick >= green_duration // 2 and direction == 'S':
                total += 1
        elif direction in ('E', 'W'):
            if tick < e_green_ticks and direction == 'E':
                total += 1
            elif tick >= green_duration // 2 and direction == 'W':
                total += 1
    return total
